    dipole = adcs_vec3_cross(field_body_t, &desired_torque);
    dipole = adcs_vec3_scale(&dipole, 1.0 / b_norm_sq);

    dipole_norm = adcs_vec3_norm(&dipole);
    if (dipole_norm > max_dipole_a_m2) {
        scale_factor = max_dipole_a_m2 / dipole_norm;
        dipole = adcs_vec3_scale(&dipole, scale_factor);
